<script setup>import {ref,onMounted,computed} from 'vue';import {api,money,toast} from '../core';import State from '../components/State.vue';const items=ref([]),loading=ref(false),error=ref(''),busy=ref(false);const selected=computed(()=>items.value.filter(i=>i.selected)),total=computed(()=>selected.value.reduce((s,i)=>s+i.price*i.quantity,0));async function load(){loading.value=true;error.value='';try{items.value=(await api('/cart')).items}catch(e){error.value=e.message}finally{loading.value=false}}async function update(i,q,s){busy.value=true;try{items.value=(await api('/cart/'+i.productId,'PUT',{quantity:Number(q),selected:!!s})).items}catch(e){toast(e.message,true);await load()}finally{busy.value=false}}async function remove(i){busy.value=true;try{items.value=(await api('/cart/'+i.productId,'DELETE')).items}catch(e){toast(e.message,true)}finally{busy.value=false}}onMounted(load);</script><template><section class="shell section"><p class="eyebrow">A LITTLE CARE IN YOUR BAG</p><h1>为它准备的好物</h1><State :loading="loading" :error="error" :empty="!items.length" text="购物车还是空的，去挑选一些好物吧" @retry="load"/><div v-if="!loading&&!error&&items.length" class="cart-layout"><div class="panel cart-items"><article class="cart-row" v-for="i in items" :key="i.productId"><input type="checkbox" :checked="i.selected" :disabled="busy" :aria-label="'选择'+i.name" @change="update(i,i.quantity,$event.target.checked)"><img :src="i.image" :alt="i.name"><div><RouterLink :to="'/shop/'+i.productId"><h3>{{i.name}}</h3></RouterLink><p class="muted">¥{{money(i.price)}} · 库存 {{i.stock}}</p><p v-if="!i.listed||i.stock<i.quantity" class="error">商品已下架或库存不足，请调整</p><button class="text-button" :disabled="busy" @click="remove(i)">移除</button></div><input class="quantity" type="number" min="1" :value="i.quantity" :max="i.stock" :disabled="busy" :aria-label="i.name+'数量'" @change="update(i,$event.target.value,i.selected)"><strong>¥{{money(i.price*i.quantity)}}</strong></article></div><aside class="panel summary"><h3>准备好了吗？</h3><div class="row between"><span>已选 {{selected.length}} 件商品</span><strong>¥{{money(total)}}</strong></div><p class="hint">结算页核对满减及八折后的实际应付金额。购物车不预占库存。</p><RouterLink v-if="selected.length&&!busy" to="/checkout" class="btn wide">去结算 →</RouterLink><button v-else class="btn wide" disabled>请先选择商品</button><RouterLink to="/shop" class="quiet-link">继续逛逛</RouterLink></aside></div></section></template>
